import '@gravity-ui/uikit/styles/fonts.css';
import '@gravity-ui/uikit/styles/styles.css';
import React from 'react';
import ReactDOM from 'react-dom/client';
import {ThemeProvider} from '@gravity-ui/uikit';
import Yagr from '@gravity-ui/yagr';
import {CpuLoadChart} from '../src/monitoring/CpuLoadChart';
import {createMockCpuLoadSource} from '../src/monitoring/cpuLoadSource';

const w = window as any;
w.__stats = {created: 0, disposed: 0, subs: 0, unsubs: 0, setData: 0, lastLen: 0, instances: []};
const origDispose = Yagr.prototype.dispose;
Yagr.prototype.dispose = function () { w.__stats.disposed++; return origDispose.call(this); };
const origBatch = (Yagr.prototype as any).batch;
(Yagr.prototype as any).batch = function (fn: any) {
  if (!w.__stats.instances.includes(this)) { w.__stats.instances.push(this); w.__stats.created++; }
  const t = performance.now(); const r = origBatch.call(this, fn); w.__stats.lastBatchMs = performance.now() - t;
  w.__stats.lastLen = this.config.timeline.length; w.__stats.setData++; return r;
};
const base = createMockCpuLoadSource();
const source = {
  fetchHistory: base.fetchHistory,
  subscribe(l: any) { w.__stats.subs++; const u = base.subscribe(l); return () => { w.__stats.unsubs++; u(); }; },
};
function Harness() {
  const [theme, setTheme] = React.useState<'light'|'dark'>('light');
  const [mounted, setMounted] = React.useState(true);
  const [width, setWidth] = React.useState(900);
  w.__setTheme = setTheme; w.__setMounted = setMounted; w.__setWidth = setWidth;
  return <ThemeProvider theme={theme}><div style={{padding: 24, width, height: 420}}>{mounted && <CpuLoadChart source={source} />}</div></ThemeProvider>;
}
ReactDOM.createRoot(document.getElementById('root')!).render(<React.StrictMode><Harness /></React.StrictMode>);
EOF
